/// <summary>
/// to change the item site level field called Item status to 'Active', 'Discontinued', or 'Deleted'.
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange
/// </summary>
public class METChangeItemStatusUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField ItemStatus;

}

Method.Source:
/// <summary>
/// Post method
/// MPJ_22974_BMSProductMDRItemStatusAndPackChange
/// </summary>
public void postBuild()
{
    super();
 
    // get references to dialog controls after creation
    ItemStatus = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METChangeItemStatusContract, parmMETItemStatus));
}

    /// <summary>
    /// Post run method
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange
    /// </summary>
    public void postRun()
    {
        super();
     
        // register overrides for form control events
        ItemStatus.registerOverrideMethod(methodstr(FormStringControl, validate),
                methodstr(METChangeItemStatusUIBuilder, validateItemStatus), this);

        ItemStatus.registerOverrideMethod(methodstr(FormStringControl, lookup),
                methodstr(METChangeItemStatusUIBuilder, lookupItemStatus), this);
    }

    /// <summary>
    /// Validate value with the master table
    /// MPJ_22974_BMSProductMDRItemStatusAndPackChange
    /// </summary>
    /// <param name = "_itemStatus">item status control</param>
    /// <returns>boolean value</returns>
    public boolean validateItemStatus(FormStringControl _itemStatus)
    {
        if(_itemStatus.valueStr())
        {
            METItemStatusTable  metItemStatusTable;

            select firstonly ItemStatus from metItemStatusTable where metItemStatusTable.ItemStatus == _itemStatus.valueStr();
            if (!metItemStatusTable)
            {
                error("@MET:InvalidItemStatus");
                return false;
            }
        }
        return true;
    }

    /// <summary>
    /// Lookup for item status
    /// </summary>
    /// <param name = "_formStringControl">item status control</param>
    public void lookupItemStatus(FormStringControl _formStringControl)
    {
        Query                   query = new Query();
        QueryBuildDataSource    qbds;
        SysTableLookup          sysTableLookup;        

        if (_formStringControl != null)
        {
            // Create an instance of SysTableLookup with
            // the current calling form control.

            sysTableLookup = SysTableLookup::newParameters(tablenum(METItemStatusTable), _formStringControl);
            sysTableLookup.addLookupfield(fieldnum(METItemStatusTable, ItemStatus), true);
            sysTableLookup.addLookupfield(fieldnum(METItemStatusTable, Description),false);
            
            qbds = query.addDataSource(tableNum(METItemStatusTable));              
            sysTableLookup.parmUseLookupValue(false);

            sysTableLookup.parmQuery(query);

            // Perform the lookup.
            sysTableLookup.performFormLookup();

        }
    }
